import {CHAPTERS,chapterKeys,CASES} from './curriculum.js';
import {PACKETS} from './packets.js';
import {subnet,tcpAck,delays,mss,fragment} from './calculators.js';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:4}).format(n);
const table=(headers,rows)=>`<div class="table-scroll"><table class="study-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const facts=items=>`<dl class="result-facts">${items.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;
const input=(name,label,value,type='text')=>`<label class="calculator-input">${label}<input name="${name}" type="${type}" value="${value}" ${type==='number'?'step="any"':''} required></label>`;

export class LearningHub{
 constructor(root,onSelect){this.root=root;this.onSelect=onSelect;this.layerId='application';this.tab='theory';this.packet='tcp';this.field='tcp-seq';this.open=new Map();this.render();}
 setLayer(id){if(id===this.layerId)return;this.layerId=id;const heading=this.root.querySelector('#study-context');if(heading)heading.textContent=chapterKeys(id).map(k=>CHAPTERS[k].name).join(' · ');if(this.tab==='theory')this.renderBody();}
 jump(tab){this.tab=tab;this.render();this.root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}
 render(){this.root.innerHTML=`<div class="study-heading"><div><span class="eyebrow">04 / DEEPER UNDERSTANDING</span><h3>Understand it, then explain it</h3><p>Learn principles with the 3D model, inspect fields, and explore practical problems through calculations and troubleshooting.</p></div><a href="../network-atlas-source.zip" class="download-source" download>Complete source ↓</a></div><div class="study-context"><span class="status-dot"></span> Current layer: <b id="study-context">${chapterKeys(this.layerId).map(k=>CHAPTERS[k].name).join(' · ')}</b></div><nav class="study-tabs" aria-label="Further learning sections">${[['theory','Principles'],['fields','Packet fields'],['tools','Calculators'],['cases','Troubleshooting']].map(([key,title])=>`<button data-study-tab="${key}" class="${key===this.tab?'active':''}" aria-pressed="${key===this.tab}">${title}</button>`).join('')}</nav><div id="study-body"></div>`;this.root.querySelectorAll('[data-study-tab]').forEach(btn=>btn.addEventListener('click',()=>{this.tab=btn.dataset.studyTab;this.render();}));this.renderBody();}
 renderBody(){const body=this.root.querySelector('#study-body');if(this.tab==='theory')body.innerHTML=this.theory();if(this.tab==='fields'){body.innerHTML=this.fields();this.bindFields();}if(this.tab==='tools'){body.innerHTML=this.tools();this.bindTools();}if(this.tab==='cases')body.innerHTML=this.cases();body.querySelectorAll('details[data-study-open]').forEach(el=>el.addEventListener('toggle',()=>this.open.set(el.dataset.studyOpen,el.open)));}
 details(key,title,content,defaultOpen=false,extra=''){return `<details class="study-detail ${extra}" data-study-open="${key}" ${this.open.has(key)?this.open.get(key)?'open':'':defaultOpen?'open':''}><summary>${title}</summary><div class="study-detail-body">${content}</div></details>`;}
 theory(){return chapterKeys(this.layerId).map(key=>{const c=CHAPTERS[key];return `<div class="chapter-head"><h4>${c.name} · Learning objectives</h4><ul class="goal-list">${c.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></div>${c.lessons.map((l,i)=>this.details(`lesson-${key}-${i}`,`<span class="lesson-index">${String(i+1).padStart(2,'0')}</span>${esc(l.title)}`,l.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')+(l.formula?`<div class="study-formula">${esc(l.formula)}</div>`:'')+(l.example?`<div class="worked-example"><b>Example / scenario</b><p>${esc(l.example)}</p></div>`:''),i===0)).join('')}`;}).join('');}
 fields(){const p=PACKETS[this.packet];let grid;if(p.rows)grid=`<div class="packet-bit-scale"><span>0</span><span>15</span><span>31 bit</span></div><div class="packet-bit-grid">${p.rows.map(row=>`<div class="packet-bit-row">${row.map(f=>`<button style="flex:${f.bits}" data-field="${f.id}" class="${this.field===f.id?'active':''}" aria-pressed="${this.field===f.id}"><b>${esc(f.label)}</b><small>${f.bits} bit</small></button>`).join('')}</div>`).join('')}</div>`;else grid=`<div class="packet-sequence">${p.sequence.map(f=>`<button data-field="${f.id}" class="${this.field===f.id?'active':''}" aria-pressed="${this.field===f.id}"><b>${esc(f.label)}</b><small>${f.bits?f.bits/8+' bytes':'Variable'}</small></button>`).join('')}</div>`;const all=p.rows?p.rows.flat():p.sequence;const f=all.find(f=>f.id===this.field)||all[0];return `<div class="packet-pickers">${Object.entries(PACKETS).map(([k,p])=>`<button data-packet="${k}" class="${k===this.packet?'active':''}">${p.name}</button>`).join('')}</div><p class="study-intro">Select a field to inspect its length, meaning and example value.</p>${grid}<div class="field-explanation" aria-live="polite"><span class="eyebrow">SELECTED FIELD</span><h4>${esc(f.label)}</h4><p>${esc(f.description)}</p><code>${esc(f.example)}</code></div><p class="study-footnote">${esc(p.note)}</p><button class="study-link" id="field-layer">Locate this layer in 3D ↗</button>`;}
 bindFields(){this.root.querySelectorAll('[data-packet]').forEach(btn=>btn.addEventListener('click',()=>{this.packet=btn.dataset.packet;const p=PACKETS[this.packet];this.field=(p.rows?p.rows.flat():p.sequence)[0].id;this.renderBody();}));this.root.querySelectorAll('[data-field]').forEach(btn=>btn.addEventListener('click',()=>{this.field=btn.dataset.field;this.renderBody();}));this.root.querySelector('#field-layer').addEventListener('click',()=>this.onSelect(PACKETS[this.packet].layer));}
 tools(){return `<p class="study-intro">Enter parameters to see results and derivations. Each calculator states its assumptions; teaching formulas do not apply to every real network.</p>
 ${this.details('tool-subnet','① CIDR and IPv4 address ranges',`<form data-calc="subnet"><div class="calculator-grid">${input('ip','IPv4 address','192.168.10.130')}${input('prefix','Prefix length /p','26','number')}</div><button class="calculate-button">Calculate address range</button><div class="calculator-result" aria-live="polite"></div></form>`,true)}
 ${this.details('tool-ack','② TCP sequence and acknowledgment numbers',`<form data-calc="ack"><div class="calculator-grid">${input('seq','Sequence number seq','1001','number')}${input('payload','Contiguous data bytes','500','number')}</div><div class="checkbox-row"><label><input type="checkbox" name="syn">Include SYN</label><label><input type="checkbox" name="fin">Include FIN</label></div><button class="calculate-button">Calculate next expected ack</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 ${this.details('tool-delay','③ Transmission, propagation and BDP',`<form data-calc="delay"><div class="calculator-grid">${input('bytes','Packet length (bytes)','1500','number')}${input('mbps','Link rate (Mb/s)','100','number')}${input('km','Link distance (km)','1000','number')}${input('velocity','Propagation speed (m/s)','200000000','number')}</div><button class="calculate-button">Calculate delay</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 ${this.details('tool-mss','④ MTU and TCP data limit',`<form data-calc="mss"><div class="calculator-grid">${input('mtu','Path MTU (bytes)','1500','number')}<label class="calculator-input">IP version<select name="version"><option value="4">IPv4 (20-byte base header)</option><option value="6">IPv6 (40-byte base header)</option></select></label>${input('tcp','TCP header (bytes)','20','number')}</div><button class="calculate-button">Calculate simplified MSS</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 ${this.details('tool-fragments','⑤ IPv4 fragments and offsets',`<form data-calc="fragments"><div class="calculator-grid">${input('payload','Original IP payload (bytes, no header)','4000','number')}${input('mtu','Next-hop MTU (bytes)','1500','number')}${input('header','IPv4 header per fragment (bytes)','20','number')}</div><button class="calculate-button">Inspect fragmentation</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 `;}
 bindTools(){this.root.querySelectorAll('[data-calc]').forEach(form=>{const calculate=()=>{const data=new FormData(form),get=k=>data.get(k),out=form.querySelector('.calculator-result');try{let result='';switch(form.dataset.calc){case'subnet':{const r=subnet(get('ip'),get('prefix'));result=facts([['Subnet mask',r.mask],['Network / prefix start',`${r.network}/${r.prefix}`],['Broadcast',r.broadcast],['First usable address',r.first],['Last usable address',r.last],['Total / usable addresses',`${format(r.total)} / ${format(r.usable)}`]])+`<code class="calculation-line">Binary address: ${r.binary}</code><p>${r.note}</p>`;break;}case'ack':{const r=tcpAck(get('seq'),get('payload'),data.has('syn'),data.has('fin'));result=facts([['Next expected ack',r.ack],['Sequence numbers consumed',r.used]])+`<code class="calculation-line">${r.formula}</code><p>${r.note}</p>`;break;}case'delay':{const r=delays(get('bytes'),get('mbps'),get('km'),get('velocity'));result=facts([['Transmission delay',`${format(r.transmission)} ms`],['One-way propagation delay',`${format(r.propagation)} ms`],['Simplified one-way total',`${format(r.total)} ms`],['Simplified propagation BDP',`${format(r.bdp)}  bytes`]])+'<code class="calculation-line">Transmission: bytes×8 ÷ bit rate; propagation: distance ÷ speed</code>'+`<p>${r.note}</p>`;break;}case'mss':{const r=mss(get('mtu'),get('version'),get('tcp'));result=facts([['Simplified TCP data limit',`${r.mss}  bytes`]])+`<code class="calculation-line">${get('mtu')} − ${r.ipHeader} − ${r.tcpHeader} = ${r.mss}</code><p>${r.note}</p>`;break;}case'fragments':{const r=fragment(get('payload'),get('mtu'),get('header'));result=table(['Fragment','Data bytes','IP total length','Offset / 8 bytes','MF'],r.map(f=>[f.number,f.payload,f.total,f.offset,f.mf]))+'<p>IPv4 fragmentation is allowed. Fragments retain the original identification. Nonfinal payloads align to 8 bytes; equal header lengths are assumed here.</p>';break;}}out.innerHTML=result;out.classList.remove('error');}catch(e){out.textContent=e.message;out.classList.add('error');}};form.addEventListener('submit',e=>{e.preventDefault();calculate();});calculate();});}
 cases(){return `<p class="study-intro">Form a hypothesis from symptoms, inspect clues and commands, then review the conclusion. Replace example domains and interface names before using commands.</p>${CASES.map(c=>this.details('case-'+c.id,`<span class="case-layer">${CHAPTERS[c.layer].name}</span>${esc(c.title)}`,`<p><b>Symptom: </b>${esc(c.symptom)}</p><details class="case-reveal"><summary>① Show diagnostic clues</summary><ol>${c.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details><details class="case-reveal"><summary>② Show troubleshooting commands</summary>${c.commands.map(([os,cmd])=>`<b class="command-os">${esc(os)}</b><pre><code>${esc(cmd)}</code></pre>`).join('')}</details><details class="case-reveal"><summary>③ Show analysis and conclusion</summary><p>${esc(c.conclusion)}</p></details>`)).join('')}`;}
}
